178: Value FFI::FFIPrepCif(const Napi::CallbackInfo& args) {
179:   Env env = args.Env();
180: 
181:   if (!args[0].IsBuffer())
182:     throw TypeError::New(env, "prepCif(): Buffer required as cif arg");
183:   if (!args[2].IsBuffer())
184:     throw TypeError::New(env, "prepCif(): Buffer required as rtype arg");
185:   if (!args[3].IsBuffer())
186:     throw TypeError::New(env, "prepCif(): Buffer required as atypes arg");
187: 
188:   ffi_cif* cif = GetBufferData<ffi_cif>(args[0]);
189:   uint32_t nargs = args[1].ToNumber();
190:   ffi_type* rtype = GetBufferData<ffi_type>(args[2]);
191:   ffi_type** atypes = GetBufferData<ffi_type*>(args[3]);
192:   ffi_abi abi = static_cast<ffi_abi>(args[4].ToNumber().Int32Value());
193: 
194:   ffi_status status = ffi_prep_cif(cif, abi, nargs, rtype, atypes);
195: 
196:   return Number::New(env, status);
197: }
