234: /*
235:  * JS wrapper around `ffi_call()`.
236:  *
237:  * args[0] - Buffer - the `ffi_cif *`
238:  * args[1] - Buffer - the C function pointer to invoke
239:  * args[2] - Buffer - the `void *` buffer big enough to hold the return value
240:  * args[3] - Buffer - the `void **` array of pointers containing the arguments
241:  */
242: 
243: void FFI::FFICall(const Napi::CallbackInfo& args) {
244:   Env env = args.Env();
245:   if (!args[0].IsBuffer() || !args[1].IsBuffer() ||
246:       !args[2].IsBuffer() || !args[3].IsBuffer()) {
247:     throw TypeError::New(env, "ffi_call() requires 4 Buffer arguments!");
248:   }
249: 
250:   ffi_cif* cif = GetBufferData<ffi_cif>(args[0]);
251:   char* fn = GetBufferData<char>(args[1]);
252:   char* res = GetBufferData<char>(args[2]);
253:   void** fnargs = GetBufferData<void*>(args[3]);
254: 
255:   ffi_call(cif, FFI_FN(fn), static_cast<void*>(res), fnargs);
256: }
