258: /*
259:  * Asynchronous JS wrapper around `ffi_call()`.
260:  *
261:  * args[0] - Buffer - the `ffi_cif *`
262:  * args[1] - Buffer - the C function pointer to invoke
263:  * args[2] - Buffer - the `void *` buffer big enough to hold the return value
264:  * args[3] - Buffer - the `void **` array of pointers containing the arguments
265:  * args[4] - Function - the callback function to invoke when complete
266:  */
267: 
268: void FFI::FFICallAsync(const Napi::CallbackInfo& args) {
269:   Env env = args.Env();
270:   if (!args[0].IsBuffer() || !args[1].IsBuffer() ||
271:       !args[2].IsBuffer() || !args[3].IsBuffer()) {
272:     throw TypeError::New(env, "ffi_call_async() requires 4 Buffer arguments!");
273:   }
274:   if (!args[4].IsFunction()) {
275:     throw TypeError::New(env, "ffi_call_async() requires a function argument");
276:   }
277: 
278:   // store a persistent references to all the Buffers and the callback function
279:   AsyncCallParams* p = new AsyncCallParams(env);
280:   p->cif = GetBufferData<ffi_cif>(args[0]);
281:   p->fn = GetBufferData<char>(args[1]);
282:   p->res = GetBufferData<char>(args[2]);
283:   p->argv = GetBufferData<void*>(args[3]);
284: 
285:   p->result = FFI_OK;
286:   p->callback = Reference<Function>::New(args[4].As<Function>(), 1);
287:   p->req.data = p;
288: 
289:   uv_queue_work(get_uv_event_loop(env),
290:                 &p->req,
291:                 FFI::AsyncFFICall,
292:                 FFI::FinishAsyncFFICall);
293: }
294: 
295: /*
296:  * Called on the thread pool.
297:  */
298: void FFI::AsyncFFICall(uv_work_t* req) {
299:   AsyncCallParams* p = static_cast<AsyncCallParams*>(req->data);
300: 
301:   try {
302:     ffi_call(p->cif, FFI_FN(p->fn), p->res, p->argv);
303:   } catch (std::exception& e) {
304:     p->err = e.what();
305:   }
306: }
307: 
308: /*
309:  * Called after the AsyncFFICall function completes on the thread pool.
310:  * This gets run on the main loop thread.
311:  */
312: 
313: void FFI::FinishAsyncFFICall(uv_work_t* req, int status) {
314:   AsyncCallParams* p = static_cast<AsyncCallParams*>(req->data);
315:   Env env = p->env;
316:   HandleScope scope(env);
317: 
318:   std::vector<napi_value> argv = { env.Null() };
319:   if (p->result != FFI_OK) {
320:     argv[0] = String::New(env, p->err);
321:   }
322: 
323:   // invoke the registered callback function
324:   // TODO: Track napi_async_context properly
325:   p->callback.MakeCallback(Object::New(env), argv);
326: 
327:   // free up our memory (allocated in FFICallAsync)
328:   delete p;
329: }
