27	void CallbackInfo::DispatchToV8(callback_info* info, void* retval, void** parameters, bool dispatched) {
28	  Env env = info->instance_data->env;
29	  HandleScope handle_scope(env);
30	
31	  static const char* errorMessage =
32	      "ffi fatal: callback has been garbage collected!";
33	
34	  try {
35	    if (info->function.IsEmpty() || info->function.Value().IsEmpty()) {
36	      // throw an error instead of segfaulting.
37	      // see: https://github.com/rbranson/node-ffi/issues/72
38	      if (dispatched) {
39	        info->errorFunction.MakeCallback(Object::New(env),
40	                                         { String::New(env, errorMessage) });
41	      } else {
42	        throw Error::New(env, errorMessage);
43	      }
44	    } else {
45	      // invoke the registered callback function
46	      Value e = info->function.MakeCallback(Object::New(env), {
47	        WrapPointer(env, retval, info->resultSize),
48	        WrapPointer(env, parameters, sizeof(char*) * info->argc)
49	      });
50	      if (!e.IsUndefined()) {
51	        if (dispatched) {
52	          info->errorFunction.Call({ e });
53	        } else {
54	          throw Error::New(env, e.ToString());
55	        }
56	      }
57	    }
58	  } catch (Error& err) {
59	    err.ThrowAsJavaScriptException();
60	  }
61	}
